import re
import time
from taf.ul.trs_e2e_fw.lib.remote_connection.ssh_library.ssh_controller import SshController
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.log_collection.exceptions import FailedToCaptureEmilLog
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from ute_common_store.store import Store

logger = BackgroundLogger.Instance()


class EmilLogOperations:
    INSTANCE = None

    def __init__(self):
        self.bts_name = "eNB" + get_config_variable(["bts_id"])
        self.ssh_conn = SshController()
        self.store = Store()

    @classmethod
    def get_instance(cls):
        if not cls.INSTANCE:
            cls.INSTANCE = EmilLogOperations()
        return cls.INSTANCE

    def start_emil_log_capture(self, **kwargs):
        """
        Starts the syslog traces with Emil

        :param kwargs:
            string sack_name: Name of the IDA sack file, Mandatory
            string host_ip: IP address of the host to start EMIL log capture, default '127.0.0.1'
            string alias: Execution context, default 'emil_alias'
            string emil_path: Path to emil directory, default '/opt/Nokia/emil/'
            string test_name: Name of the test to be passed to start EMIL interface, default 'test1'

        :return: Path to generated EMIL logs
        :rtype: list

        :exceptions:

        """
        sack_name = kwargs["sack_name"]
        host_ip = kwargs.get("host_ip", "127.0.0.1")
        alias = kwargs.get("alias", "emil_alias")
        emil_path = kwargs.get("emil_path", "/opt/Nokia/emil")
        test_name = kwargs.get("test_name", "test1")
        file_to_import = "eNB_{}".format(self.bts_name)

        sack_path = emil_path + "/Sacks"
        emil_start_cmd = "{0}/run_emil --sackpath {1}/{2} --name {3} --noscreen".format(emil_path, sack_path, sack_name,
                                                                                        test_name)
        logger.debug("################ Start EMIL Interface #################################")
        self._start_emil_interface(host_ip=host_ip, emil_start_cmd=emil_start_cmd, alias=alias)
        logger.debug("################ Connect to enb #################################")
        self._connect_to_enb(alias=alias, emil_path=emil_path, file_name=file_to_import, bts_name=self.bts_name)
        logger.debug("################ Start Syslog and EMIL log capture #################################")
        emil_logs = self._start_syslog_capture(alias=alias, bts_name=self.bts_name)
        self.store.add(emil_logs, alias)
        return emil_logs

    def execute_command_on_emil_interface(self, **kwargs):
        """
        Execute commands supported by EMIL interface

        :param kwargs:
            string command: Name of the IDA sack file, Mandatory
            string exit_prompt: Exit prompt to be matched, default 'Emil>'
            int timeout: timeout from execution interface, default 30
            string alias: Execution context, default 'emil_alias'

        :returns: console output
        :rtype: string
        """
        command = kwargs["command"]
        exit_prompt = kwargs.get("exit_prompt", "Emil>")
        timeout = kwargs.get("timeout", 30)
        alias = kwargs.get("alias", "emil_alias")

        return self.ssh_conn.execute_command_on_shell(command, alias, exit_prompt=exit_prompt, timeout=timeout)

    def stop_emil_log_capture(self, **kwargs):
        """
        Stops the syslog traces with Emil

        :param kwargs:
            string alias: Execution context, default 'emil_alias'

        :returns: NA
        :rtype: NA
        """
        alias = kwargs.get("alias", "emil_alias")
        self._stop_syslog_capture(alias=alias, bts_name=self.bts_name)
        self._disconnect_from_enb(alias=alias, bts_name=self.bts_name)
        self._exit_emil_interface(alias=alias)
        self._copy_emil_logs(alias=alias)
        self.ssh_conn.close_ssh_session_with_host(alias=alias)

    def _copy_emil_logs(self, alias):
        """
        Copy generated EMIL logs to execution_logs directory

        :param string alias: Name os execution context, Mandatory

        :returns: NA
        :rtype: NA
        """
        log_dir = 'execution_logs/'
        emil_logs = self.store.get(alias)
        if not emil_logs:
            raise FailedToCaptureEmilLog("Logs are not captured. Make sure correct configurations are loaded")
        for log in emil_logs:
            self.ssh_conn.get_file_from_host(log, log_dir, alias)

    def _start_emil_interface(self, host_ip, emil_start_cmd, alias):
        """
        Start EMIL interface

        :param int host_ip: IP address of the host to start EMIL log capture, Mandatory
        :param string emil_start_cmd: command to start EMIL interface, Mandatory
        :param string alias: Name os execution context, Mandatory

        :returns: NA
        :rtype: NA
        """
        host_details = {"ip": host_ip, "user": None, "password": None}
        self.ssh_conn.establish_ssh_connection_with_host(host_details=host_details, timeout=30, alias=alias)
        self.ssh_conn.execute_command_on_shell(emil_start_cmd, alias, exit_prompt="Emil>", timeout=30)

    def _exit_emil_interface(self, alias, exit_prompt="$", timeout=30):
        """
        Exit Emil completely

        :param string alias: Name os execution context, Mandatory
        :param string exit_prompt: exit prompt to be matched, default "$"
        :param int timeout: timeout from the execution interface, default 30

        :returns: NA
        :rtype: NA

        """
        self.ssh_conn.execute_command_on_shell("exit", alias=alias, exit_prompt=exit_prompt, timeout=timeout)

    def _connect_to_enb(self, alias, emil_path, file_name, bts_name):
        """
        Connect to selected BTS name

        :param string emil_path: exit prompt to be matched, Mandatory
        :param string file_name: timeout from the execution interface, Mandatory
        :param string bts_name: timeout from the execution interface, Mandatory
        :param string alias: Name os execution context, Mandatory


        :returns: NA
        :rtype: NA
        """
        import_cmd = "import {0}/{1}".format(emil_path, file_name)
        connect_cmd = "connect {0}".format(bts_name)
        self.ssh_conn.execute_command_on_shell(import_cmd, alias,
                                               exit_prompt="Emil>", timeout=30)
        self.ssh_conn.execute_command_on_shell("\n", alias, exit_prompt="Emil>")
        self.ssh_conn.execute_command_on_shell("\n", alias, exit_prompt="Emil>")
        self.ssh_conn.execute_command_on_shell(connect_cmd, alias, exit_prompt="Emil>",
                                               timeout=30)
        time.sleep(20)
        self.ssh_conn.execute_command_on_shell("\n", alias, exit_prompt="Emil>")
        self.ssh_conn.execute_command_on_shell("\n", alias, exit_prompt="Emil>")

    def _disconnect_from_enb(self, alias, bts_name):
        """
        Disconnect from selected BTS name
        """
        self.ssh_conn.execute_command_on_shell("disconnect {0}".format(bts_name), alias, exit_prompt="Emil>",
                                               timeout=30)

    def _start_syslog_capture(self, alias, bts_name):
        """
        Starts the syslog traces with Emil
        """
        start_sys_cmd = "syslog start {0}".format(bts_name)
        self.ssh_conn.execute_command_on_shell(start_sys_cmd, alias, exit_prompt="Emil>",
                                               timeout=30)
        time.sleep(20)
        self.ssh_conn.execute_command_on_shell("\n", alias, exit_prompt="Emil>")
        self.ssh_conn.execute_command_on_shell("\n", alias, exit_prompt="Emil>")
        log_name = self._get_log_file(alias=alias)
        return log_name

    def _stop_syslog_capture(self, alias, bts_name):
        """
        Stops the syslog traces
        """
        stop_sys_cmd = "syslog stop {0}".format(bts_name)
        self.ssh_conn.execute_command_on_shell(stop_sys_cmd, alias, exit_prompt="Emil>",
                                               timeout=30)

    def _get_log_file(self, alias):
        """
        Get the snapshots/emil files created in this session, default is within last 96 hours
        """
        log_name = ""
        self._get_emil_info(alias=alias)
        resp = self.ssh_conn.execute_command_on_shell("files", alias, exit_prompt="Emil>", timeout=30)
        last_index = resp.rindex(r'=')
        first_index = resp.index(r'=')
        log_name = resp[first_index + 1:last_index].strip().replace("=", "")
        log_list = re.split('\(recent\)', log_name, 10)
        if len(log_list) == 1:
            logger.warn("Logs are not captured. Make sure correct configurations are loaded")
            return None
        all_logs = []
        for item in log_list:
            if len(item) > 10:
                all_logs.append(item[0:item.strip().index(" ") + 2].strip())
        return all_logs

    def _get_emil_info(self, alias):
        """
        Gets EMIL info
        """
        emil_info_dict = {}
        emil_info = self.ssh_conn.execute_command_on_shell("info", alias, exit_prompt="Emil>", timeout=30)
        emil_info_dict["Logs Directory"] = emil_info[emil_info.rindex(r"Logs Directory"):
                                                     emil_info.rindex(r"Current Sack")].split("=")[1].strip()

        emil_info_dict["Data Directory"] = emil_info[emil_info.rindex(r"Data Directory"):
                                                     emil_info.rindex(r"Logs Directory")].split("=")[1].strip()

        emil_info_dict["Current Sack"] = emil_info[emil_info.rindex(r"Current Sack"):
                                                   emil_info.rindex(r"Profile Path")].split("=")[1].strip()

        emil_info_dict["Profile Path"] = emil_info[emil_info.rindex(r"Profile Path"):
                                                   emil_info.rindex(r"Trigger XML")].split("=")[1].strip()
        self.ssh_conn.execute_command_on_shell("\n", alias, exit_prompt="Emil>", timeout=30)
        return emil_info_dict
